--
-- Table structure for table `bookings`
--

DROP TABLE IF EXISTS `bookings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bookings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `booking_code` varchar(16) NOT NULL,
  `user_id` bigint NOT NULL,
  `vehicle_id` bigint NOT NULL,
  `charging_point_id` bigint NOT NULL,
  `station_id` bigint NOT NULL,
  `start_time` datetime NOT NULL,
  `end_time` datetime NOT NULL,
  `slots` int NOT NULL,
  `status` varchar(12) NOT NULL,
  `source` varchar(12) NOT NULL DEFAULT 'WEB',
  `soc_start` int NOT NULL,
  `soc_target` int NOT NULL,
  `est_energy_kwh` double NOT NULL,
  `est_cost` decimal(10,2) NOT NULL,
  `created_at` datetime NOT NULL,
  `hold_expires_at` datetime DEFAULT NULL,
  `checked_in_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `cancel_reason` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `booking_code` (`booking_code`),
  KEY `fk_bk_vehicle` (`vehicle_id`),
  KEY `idx_bk_user_start` (`user_id`,`start_time`),
  KEY `idx_bk_station_start` (`station_id`,`start_time`),
  KEY `idx_bk_point_start` (`charging_point_id`,`start_time`),
  KEY `idx_bk_status_start` (`status`,`start_time`),
  CONSTRAINT `fk_bk_point` FOREIGN KEY (`charging_point_id`) REFERENCES `charging_points` (`id`),
  CONSTRAINT `fk_bk_station` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`),
  CONSTRAINT `fk_bk_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_bk_vehicle` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9543 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

