--
-- Table structure for table `reviews`
--

DROP TABLE IF EXISTS `reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reviews` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `station_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `booking_id` bigint DEFAULT NULL,
  `rating` int NOT NULL,
  `comment` varchar(500) DEFAULT NULL,
  `sentiment_score` double NOT NULL DEFAULT '0',
  `sentiment_label` varchar(10) NOT NULL DEFAULT 'NEUTRAL',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_rv_user` (`user_id`),
  KEY `fk_rv_booking` (`booking_id`),
  KEY `idx_rv_station` (`station_id`,`created_at`),
  CONSTRAINT `fk_rv_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`),
  CONSTRAINT `fk_rv_station` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`),
  CONSTRAINT `fk_rv_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1719 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

