DROP TABLE IF EXISTS `stations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stations` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `operator_id` bigint NOT NULL,
  `name` varchar(100) NOT NULL,
  `address` varchar(200) NOT NULL,
  `zone` varchar(40) NOT NULL,
  `city` varchar(40) NOT NULL,
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `tier` varchar(10) NOT NULL DEFAULT 'STANDARD',
  `open_hour` int NOT NULL DEFAULT '0',
  `close_hour` int NOT NULL DEFAULT '24',
  `status` varchar(12) NOT NULL DEFAULT 'ACTIVE',
  `uptime_pct` double NOT NULL DEFAULT '97',
  `avg_rating` double NOT NULL DEFAULT '0',
  `review_count` int NOT NULL DEFAULT '0',
  `sentiment_score` double NOT NULL DEFAULT '0',
  `reliability_score` double NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_station_operator` (`operator_id`),
  KEY `idx_station_zone` (`zone`),
  KEY `idx_station_geo` (`latitude`,`longitude`),
  CONSTRAINT `fk_station_operator` FOREIGN KEY (`operator_id`) REFERENCES `operators` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

