--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `full_name` varchar(100) NOT NULL,
  `email` varchar(120) NOT NULL,
  `password_hash` varchar(100) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `role` varchar(20) NOT NULL,
  `city` varchar(40) DEFAULT NULL,
  `status` varchar(12) NOT NULL DEFAULT 'ACTIVE',
  `operator_id` bigint DEFAULT NULL,
  `fleet_id` bigint DEFAULT NULL,
  `home_lat` double DEFAULT NULL,
  `home_lon` double DEFAULT NULL,
  `reminder_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `reminder_lead_hours` int NOT NULL DEFAULT '24',
  `no_show_count` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  `last_login_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `fk_users_operator` (`operator_id`),
  KEY `fk_users_fleet` (`fleet_id`),
  KEY `idx_users_role` (`role`),
  CONSTRAINT `fk_users_fleet` FOREIGN KEY (`fleet_id`) REFERENCES `fleets` (`id`),
  CONSTRAINT `fk_users_operator` FOREIGN KEY (`operator_id`) REFERENCES `operators` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=657 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

